/**
 * The channel to GitLab's REST API.
 *
 * One class, one responsibility: turn a path and a token into a JSON document,
 * and turn GitLab's refusal into a sentence the user can act on. Every read and
 * write this plugin performs goes through here — the agent's tools and the side
 * panel alike — so there is no second path to GitLab and no second error
 * vocabulary.
 *
 * The token is read per call rather than held: the settings card can replace it
 * while the process runs, and the next call then uses the new one.
 */

import type { JsonValue } from "dsh-mcp-oauth";
import { apiRootOf, type GitLabConfig } from "./config";
import type { TokenStore } from "./token";

/** How long one GitLab call may take. */
const REQUEST_TIMEOUT_MS = 30_000;

/** A query parameter's value, or undefined to leave it out. */
export type Param = string | number | boolean | undefined;

/** One document GitLab answered with, and the count it reported beside it. */
export interface Answer<T> {
	readonly value: T;
	/** The `x-total` header, when the endpoint reports one. */
	readonly total?: number;
}

/**
 * One answer whose body may be JSON, text, or bytes.
 *
 * `gitlab_read` is the plugin's generic GET, and some of the endpoints it covers
 * answer plain text — a repository file's raw contents, a job's trace — rather
 * than JSON. The caller needs to know which it got before it prints anything.
 */
export interface RawAnswer {
	/** The body decoded as JSON when it is JSON, and its text otherwise. */
	readonly value: unknown;
	/** Whether the body was JSON. */
	readonly isJson: boolean;
	/** What GitLab said it was sending, for the caller's own report. */
	readonly contentType: string;
	/** The body as text, for a text answer or a cut-down JSON one. */
	readonly text: string;
	/** Whether the body is binary and cannot be shown as text. */
	readonly isBinary: boolean;
	/** The `x-total` header, when the endpoint reports one. */
	readonly total?: number;
	/** The page GitLab said it answered, when it said one. */
	readonly page?: number;
	/** The next page's number, when GitLab names one. */
	readonly nextPage?: number;
}

/** A content type whose body is bytes rather than something a model can read. */
const BINARY_TYPE =
	/^(?:image|audio|video)\/|application\/(?:octet-stream|zip|pdf|gzip)/iu;

/** The reason inside an unknown thrown value, as a plain sentence. */
const reasonOf = (error: unknown): string =>
	error instanceof Error ? error.message : String(error);

/** One positive integer header, when it is a positive integer. */
function positiveHeader(response: Response, name: string): number | undefined {
	const raw = response.headers.get(name);
	if (raw === null || raw.trim() === "") return undefined;

	const value = Number(raw);

	return Number.isInteger(value) && value > 0 ? value : undefined;
}

/** Everything the client needs, wired once at apply time. */
export interface ApiDeps {
	readonly config: GitLabConfig;
	readonly token: TokenStore;
}

export class GitLabApi {
	constructor(private readonly deps: ApiDeps) {}

	/**
	 * Read one document.
	 * @param path - the API path, such as `/user`.
	 * @param params - query parameters; undefined values are left out.
	 */
	async get<T = JsonValue>(
		path: string,
		params?: Readonly<Record<string, Param>>,
	): Promise<T> {
		return (await this.getAnswer<T>(path, params)).value;
	}

	/**
	 * Read one document and the count GitLab reports beside it.
	 *
	 * A list endpoint answers with a page and puts the number of matches in
	 * `x-total`; a card that says "25 of 137" needs both.
	 */
	async getAnswer<T = JsonValue>(
		path: string,
		params?: Readonly<Record<string, Param>>,
	): Promise<Answer<T>> {
		const response = await this.request("GET", path, params);
		const raw = response.headers.get("x-total");
		const total = raw === null || raw.trim() === "" ? undefined : Number(raw);

		return {
			value: (await response.json()) as T,
			...(total !== undefined && Number.isFinite(total) ? { total } : {}),
		};
	}

	/**
	 * Read one endpoint without assuming its body is JSON.
	 *
	 * The generic read tool promises any GET, and not every GET answers JSON: a
	 * repository file's raw contents and a job's trace are text, an artifact is
	 * bytes. Decoding all of them through `response.json()` was what turned a
	 * perfectly good text answer into a parser failure.
	 * @param path - the API path.
	 * @param params - query parameters; undefined values are left out.
	 * @returns the decoded body, the content type, and the paging headers.
	 */
	async read(
		path: string,
		params?: Readonly<Record<string, Param>>,
	): Promise<RawAnswer> {
		const response = await this.request("GET", path, params);
		const contentType = response.headers.get("content-type") ?? "";
		const binary = BINARY_TYPE.test(contentType);

		// An artifact can be megabytes of bytes a model cannot read; cancel it rather
		// than downloading it only to report its type.
		if (binary) {
			await response.body?.cancel().catch(() => undefined);

			return {
				value: "",
				isJson: false,
				contentType,
				text: "",
				isBinary: true,
				...(positiveHeader(response, "x-total") === undefined
					? {}
					: { total: positiveHeader(response, "x-total") }),
			};
		}

		const text = await response.text();
		const page = positiveHeader(response, "x-page");
		const nextPage = positiveHeader(response, "x-next-page");
		const total = positiveHeader(response, "x-total");
		const json = /json/iu.test(contentType) || /^\s*[[{]/u.test(text);

		let value: unknown = text;
		let isJson = false;

		if (json) {
			try {
				value = JSON.parse(text) as unknown;
				isJson = true;
			} catch {
				// A body that only looks like JSON is text, and is reported as such.
			}
		}

		return {
			value,
			isJson,
			contentType,
			text,
			isBinary: false,
			...(total === undefined ? {} : { total }),
			...(page === undefined ? {} : { page }),
			...(nextPage === undefined ? {} : { nextPage }),
		};
	}

	/**
	 * Read every page of one list endpoint.
	 *
	 * GitLab slices discussions, diffs and jobs at 100 per page and reports the
	 * next page in `x-next-page`. Reading only the first page silently loses
	 * unresolved threads on a large merge request.
	 * @param path - the list's API path.
	 * @param params - the filters, without `page` or `per_page`.
	 * @param maxPages - the safety cap; a hundred pages is ten thousand rows.
	 * @returns the rows from every page that answered.
	 */
	async getAll(
		path: string,
		params?: Readonly<Record<string, Param>>,
		maxPages = 100,
	): Promise<{ readonly items: unknown[]; readonly truncated: boolean }> {
		const items: unknown[] = [];
		let page = 1;
		let truncated = false;

		for (let index = 0; index < maxPages; index += 1) {
			const response = await this.request("GET", path, {
				...params,
				page,
				per_page: 100,
			});
			const body: unknown = await response.json();

			if (!Array.isArray(body)) break;

			items.push(...body);

			const next = Number(response.headers.get("x-next-page"));

			if (!Number.isInteger(next) || next <= page) break;
			if (index === maxPages - 1) {
				truncated = true;

				break;
			}

			page = next;
		}

		return { items, truncated };
	}

	/**
	 * Write one document.
	 * @param path - the API path.
	 * @param body - the JSON body, when the endpoint takes one.
	 */
	async post<T = JsonValue>(path: string, body?: unknown): Promise<T> {
		const response = await this.request("POST", path, undefined, body);

		return (await response.json()) as T;
	}

	/** Replace part of one document. */
	async put<T = JsonValue>(path: string, body?: unknown): Promise<T> {
		const response = await this.request("PUT", path, undefined, body);

		return (await response.json()) as T;
	}

	/**
	 * Read one document that is not JSON.
	 * @param path - the API path, such as a job's trace.
	 */
	async text(path: string): Promise<string> {
		const response = await this.request("GET", path);

		return await response.text();
	}

	/** One authenticated call, with the token read at the moment it is made. */
	private async request(
		method: string,
		path: string,
		params?: Readonly<Record<string, Param>>,
		body?: unknown,
	): Promise<Response> {
		const token = await this.deps.token.read();

		if (token === undefined)
			throw new Error(
				"no GitLab personal access token stored; paste one in the GitLab settings card (the token is held by the harness and is not available to shell commands)",
			);

		const url = new URL(`${apiRootOf(this.deps.config)}${path}`);

		for (const [name, value] of Object.entries(params ?? {})) {
			if (value !== undefined) url.searchParams.set(name, String(value));
		}

		const response = await this.requestOnce(url, method, token, body);

		if (!response.ok) throw await this.failureOf(response);

		return response;
	}

	/** One fetch, with a network failure said as one. */
	private async requestOnce(
		url: URL,
		method: string,
		token: string,
		body: unknown,
	): Promise<Response> {
		try {
			return await fetch(url, {
				method,
				headers: {
					accept: "application/json",
					"private-token": token,
					...(body === undefined ? {} : { "content-type": "application/json" }),
				},
				...(body === undefined ? {} : { body: JSON.stringify(body) }),
				signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
			});
		} catch (error) {
			const seconds = REQUEST_TIMEOUT_MS / 1000;
			const timeout =
				(error instanceof Error &&
					(error.name === "TimeoutError" || error.name === "AbortError")) ||
				/timed? ?out|abort/iu.test(reasonOf(error));

			throw new Error(
				timeout
					? `GitLab did not answer ${method} ${url.pathname} within ${seconds} s; the request timed out. The same call can be retried.`
					: `Could not reach GitLab at ${url.origin} (${method} ${url.pathname}): ${reasonOf(error)}. Check the network or VPN, then retry — the same call can be retried.`,
			);
		}
	}

	/** GitLab's own words about a refusal, as one sentence. */
	private async failureOf(response: Response): Promise<Error> {
		const text = await response.text().catch(() => "");
		let message = text.trim();

		try {
			const parsed: unknown = JSON.parse(text);

			if (
				parsed !== null &&
				typeof parsed === "object" &&
				typeof (parsed as { message?: unknown }).message === "string"
			)
				message = (parsed as { message: string }).message;
			else if (
				parsed !== null &&
				typeof parsed === "object" &&
				typeof (parsed as { error?: unknown }).error === "string"
			)
				message = (parsed as { error: string }).error;
		} catch {
			// Not JSON: the body itself is what GitLab said.
		}

		if (response.status === 401)
			return new Error(
				`GitLab refused the token (401): ${message === "" ? "it may have expired, or lack the api scope" : message}`,
			);
		if (response.status === 403)
			return new Error(
				`GitLab refused the request (403): ${message === "" ? "the token's owner may not be allowed to do this" : message}`,
			);

		return new Error(
			`GitLab answered ${response.status} for ${response.url}: ${message}`,
		);
	}
}
